// ============================================================================
// AP Physics 2: Algebra-Based — original, unofficial multiple-choice practice bank
// ============================================================================
// Aligned to the AP Physics 2 Course and Exam Description (Units 9-15, the
// continuation of Physics 1's unit numbering). No released or secure College
// Board item is reproduced here. All questions, data, and scenarios are
// original practice material created for this project.
//
// g = 9.8 m/s^2, k = 8.99e9 N*m^2/C^2, e = 1.60e-19 C, R = 8.31 J/(mol*K),
// h = 6.63e-34 J*s, c = 3.00e8 m/s unless a question states otherwise.
// ============================================================================

const PHYS2_QUESTIONS = [];
const PHYS2_UNIT_COUNTS = {};
function pq(unit, topicCode, topic, skill, stem, correct, distractors, why, variantGroupId, stimulusGroupId, stimulus) {
  const number = (PHYS2_UNIT_COUNTS[unit] || 0) + 1;
  PHYS2_UNIT_COUNTS[unit] = number;
  const correctIndex = PHYS2_QUESTIONS.length % 4;
  const options = distractors.slice();
  options.splice(correctIndex, 0, correct);
  const explanation = why.length >= 90 ? why : `${why} This reasoning connects the observed or calculated result directly to the physical model in the question.`;
  PHYS2_QUESTIONS.push({
    id: `apphys2-${unit.toLowerCase()}-${String(number).padStart(3, "0")}`,
    unit, topicCode, topic, skill, type: "s", q: stem, o: options, c: [correctIndex], e: explanation,
    variantGroupId, stimulusGroupId, stimulus,
  });
}

// --------------------------------------------------------------------------
// Unit 9: Thermodynamics (6 topics)
// --------------------------------------------------------------------------
pq("U9","9.1","Kinetic Theory of Temperature and Pressure","2.A","A sample of ideal gas has its Kelvin temperature doubled while the number of molecules is held constant. What happens to the average translational kinetic energy per molecule?","It doubles.",["It quadruples.","It stays the same.","It is cut in half."],"Kinetic theory gives average translational kinetic energy per molecule as (3/2)kT, which is directly proportional to absolute temperature. Doubling T on the Kelvin scale doubles the average kinetic energy.");
pq("U9","9.1","Kinetic Theory of Temperature and Pressure","3.A","On a microscopic model, gas pressure on a container wall arises mainly from","repeated molecular collisions transferring momentum to the wall",["a static electric repulsion between gas molecules and the wall","the constant weight of gas molecules pressing downward only","molecules sticking briefly to the wall and pulling it inward"],"Kinetic theory models pressure as the macroscopic result of many molecules colliding with the walls and transferring momentum. It is not a static force, electrical effect, or adhesive interaction.");
pq("U9","9.1","Kinetic Theory of Temperature and Pressure","2.B","At the same temperature, a sample of helium (M = 4 g/mol) and a sample of argon (M = 40 g/mol) are compared. Which statement about their molecules is correct?","Helium has the greater speed, though both gases share the same kinetic energy.",["Argon molecules have the greater average speed, and the greater average kinetic energy.","Both gases have identical average speed and identical average kinetic energy.","Helium molecules have the greater average kinetic energy, but the same average speed."],"Average translational kinetic energy depends only on temperature, so it is equal for both gases here. Since KE = (1/2)mv^2 is the same for both, the much lighter helium atoms must have the higher average speed.");

pq("U9","9.2","The Ideal Gas Law","2.A","A rigid container holds 1.00 mol of ideal gas at 300 K and an absolute pressure of 1.01×10^5 Pa. Using R = 8.31 J/(mol·K), what is the gas volume?","About 0.0247 m^3",["About 0.0025 m^3","About 2.47 m^3","About 247 m^3"],"Solving PV = nRT for V gives V = nRT/P = (1.00)(8.31)(300)/(1.01×10^5) ≈ 0.0247 m^3, close to a typical molar gas volume near room temperature.");
pq("U9","9.2","The Ideal Gas Law","2.B","A sealed rigid container of ideal gas is heated from 250 K to 500 K without changing its volume or the amount of gas. If its initial absolute pressure was 1.00×10^5 Pa, what is its final pressure?","2.00×10^5 Pa",["1.00×10^5 Pa","4.00×10^5 Pa","0.50×10^5 Pa"],"At constant volume and moles, P/T is constant, so P2 = P1(T2/T1) = (1.00×10^5)(500/250) = 2.00×10^5 Pa. Doubling absolute temperature at fixed volume doubles absolute pressure.");
pq("U9","9.2","The Ideal Gas Law","2.C","An ideal gas has initial state P1 = 2.0×10^5 Pa, V1 = 0.50 m^3, T1 = 300 K. It is changed to P2 = 1.0×10^5 Pa and T2 = 450 K. What is V2?","1.5 m^3",["0.75 m^3","0.33 m^3","3.0 m^3"],"The combined gas law gives P1V1/T1 = P2V2/T2, so V2 = P1V1T2/(T1P2) = (2.0×10^5)(0.50)(450)/[(300)(1.0×10^5)] = 1.5 m^3.");
pq("U9","9.2","The Ideal Gas Law","3.B","A student doubles both the absolute temperature and the volume of a fixed amount of ideal gas in one step. Which claim about the required pressure change is correct?","Pressure stays the same, since PV/T remains constant in this process.",["Pressure must double, since temperature alone determines pressure.","Pressure must be quartered, since volume and temperature both increased.","Pressure change cannot be determined without knowing the gas's molar mass."],"From PV = nRT, if V and T both double with n fixed, P1V1/T1 = P2(2V1)/(2T1) = P2V1/T1, which requires P2 = P1. Molar mass does not appear in the ideal gas law and is not needed here.");

pq("U9","9.3","Thermal Energy Transfer and Equilibrium","1.A","A metal spoon left standing in a hot cup of soup becomes warm to the touch at its handle. This primarily illustrates which mechanism of thermal energy transfer?","Conduction, energy passed between adjacent particles in the solid metal",["Convection, bulk motion of fluid carrying energy through the spoon","Radiation, energy carried by electromagnetic waves through the metal","Evaporation, energy carried away as liquid becomes vapor"],"Conduction transfers thermal energy through direct particle-to-particle interactions within a solid, exactly as vibrational energy moves progressively along the solid metal spoon from the hot end toward the handle.");
pq("U9","9.3","Thermal Energy Transfer and Equilibrium","3.A","Two objects, initially at different temperatures, are placed in contact inside a perfectly insulated enclosure. Once they reach thermal equilibrium, which statement is necessarily true?","They reach equal temperature, not equal thermal energy.",["The two objects have exactly equal thermal energy content.","The hotter object's temperature has dropped to absolute zero.","No further microscopic energy exchange occurs between the objects."],"Thermal equilibrium is defined by equal temperature, not equal thermal energy, since the objects can have different masses or specific heats. Microscopic energy exchange continues, but the net exchange becomes zero.");
pq("U9","9.3","Thermal Energy Transfer and Equilibrium","2.D","Two rods of the same length and cross-sectional area connect a hot reservoir to a cold reservoir. Rod A has twice the thermal conductivity of rod B. Under steady-state conditions with the same temperature difference across each, how does the conductive heat-transfer rate compare?","Rod A conducts heat at twice the rate of rod B.",["Rod A conducts heat at half the rate of rod B.","Both rods conduct heat at the same rate regardless of conductivity.","Conductivity does not affect the rate of heat conduction."],"The rate of conductive heat transfer is proportional to thermal conductivity when length, area, and temperature difference are equal. Doubling conductivity doubles the steady-state conduction rate.");

pq("U9","9.4","The First Law of Thermodynamics","2.A","A gas absorbs 500 J of heat while expanding and doing 200 J of work on its surroundings. Using ΔEint = Q − W, what is the change in the gas's internal energy?","+300 J",["+700 J","−300 J","+100 J"],"With Q = +500 J entering the gas and W = +200 J done by the gas, ΔEint = Q − W = 500 − 200 = +300 J, so the internal energy increases despite the gas doing work.");
pq("U9","9.4","The First Law of Thermodynamics","3.B","A gas undergoes a process in a perfectly insulated, sealed cylinder with a frictionless piston that is pushed in by an external force, compressing the gas. Which description of this process is most accurate?","It is adiabatic, and the gas's internal energy increases because work is done on it.",["It is isothermal, so the internal energy of the gas stays constant throughout.","It is isobaric, so no work is done on or by the gas during compression.","It is impossible for the gas's internal energy to increase without heat entering it."],"A perfectly insulated cylinder allows no heat exchange, so Q = 0 and the process is adiabatic. With work done on the gas during compression, ΔEint = Q − W = 0 − (negative W) is positive, so internal energy rises even without any heat input.");
pq("U9","9.4","The First Law of Thermodynamics","2.B","An ideal gas expands at a constant pressure of 2.0×10^5 Pa, and its volume increases from 0.10 m^3 to 0.30 m^3. How much work does the gas do on its surroundings?","4.0×10^4 J",["2.0×10^4 J","6.0×10^4 J","8.0×10^4 J"],"For an isobaric process, work done by the gas is W = PΔV = (2.0×10^5)(0.30 − 0.10) = (2.0×10^5)(0.20) = 4.0×10^4 J.");
pq("U9","9.4","The First Law of Thermodynamics","3.C","A gas is compressed isothermally, meaning its temperature stays constant throughout the process. Since internal energy of an ideal gas depends only on temperature, which relationship between heat and work must hold for this process?","Q = W: heat removed equals work done on the gas.",["Q = 0, because no temperature change means no thermal effects at all.","W = 0, because compression at constant temperature requires no work.","ΔEint must be nonzero even though temperature does not change."],"For an ideal gas, ΔEint depends only on temperature, so ΔEint = 0 in an isothermal process. From ΔEint = Q − W, this forces Q = W: the heat leaving the gas during isothermal compression equals the work done on it.");

pq("U9","9.5","Specific Heat and Thermal Conductivity","2.A","How much heat is required to raise the temperature of 0.50 kg of water by 15°C? Use c(water) = 4186 J/(kg·°C).","About 3.1×10^4 J",["About 6.3×10^4 J","About 1.6×10^4 J","About 3.1×10^3 J"],"Using Q = mcΔT gives Q = (0.50)(4186)(15) ≈ 3.1×10^4 J, the heat needed to produce that temperature change in the given mass of water.");
pq("U9","9.5","Specific Heat and Thermal Conductivity","2.C","In an insulated container, 0.200 kg of water at 80°C is mixed with 0.100 kg of water at 20°C. Assuming no heat is lost to the container, what is the final equilibrium temperature?","60°C",["50°C","65°C","40°C"],"Conservation of energy requires the heat lost by the hot water to equal the heat gained by the cool water: m1(80−Tf) = m2(Tf−20) with equal specific heats. Solving gives Tf = (m1·80 + m2·20)/(m1+m2) = (0.200·80+0.100·20)/0.300 = 60°C.");
pq("U9","9.5","Specific Heat and Thermal Conductivity","3.A","Two blocks of equal mass absorb the same quantity of heat. Block X shows a much smaller temperature increase than block Y. What does this indicate about block X?","Block X has a larger specific heat capacity than block Y.",["Block X has a smaller specific heat capacity than block Y.","Block X must be a better thermal conductor than block Y.","Block X must have started at a lower initial temperature."],"From Q = mcΔT with equal Q and equal m, a smaller ΔT requires a larger c. A large specific heat capacity means more heat is needed to produce a given temperature change, which is a property distinct from conductivity or starting temperature.");

pq("U9","9.6","Entropy and the Second Law of Thermodynamics","3.A","Which process below is consistent with the second law of thermodynamics for an isolated system?","Heat spontaneously flows from a warmer object to a cooler object, increasing total entropy.",["Heat spontaneously flows from a cooler object to a warmer object with no other change.","An isolated system's total entropy spontaneously decreases while no work is done on it.","Two gases that have mixed spontaneously separate back into their original volumes."],"The second law requires the total entropy of an isolated system to not decrease over time. Spontaneous heat flow from hot to cold increases entropy, while the other options all describe entropy spontaneously decreasing, which the second law forbids.");
pq("U9","9.6","Entropy and the Second Law of Thermodynamics","2.D","In a reversible process at a constant temperature of 300 K, 1200 J of heat is transferred into a system. What is the resulting change in the system's entropy?","4 J/K",["300 J/K","0.25 J/K","1200 J/K"],"For a reversible process at constant temperature, entropy change is ΔS = Q/T = 1200/300 = 4 J/K.");
pq("U9","9.6","Entropy and the Second Law of Thermodynamics","1.B","A container is divided by a partition, with gas confined to one side and vacuum on the other. The partition is removed and the gas spreads to fill the whole container. Which statement about this process is best supported by the second law?","The gas's entropy increases because the free-expansion state has far more accessible microstates.",["The gas's entropy decreases because the molecules become more spread out and orderly.","The process violates the second law because no heat was added to the gas.","Entropy is undefined for this process since no temperature change occurs."],"Free expansion into a larger available volume increases the number of accessible molecular microstates, so entropy increases even though no heat was exchanged and temperature may not change for an ideal gas.");

// --------------------------------------------------------------------------
// Unit 10: Electric Force, Field, and Potential (7 topics)
// --------------------------------------------------------------------------
pq("U10","10.1","Electric Charge and Electric Force","2.A","Two point charges, q1 = 2.0×10^−6 C and q2 = 3.0×10^−6 C, are separated by 0.30 m. Using k = 8.99×10^9 N·m^2/C^2, what is the magnitude of the electric force between them?","About 0.60 N",["About 6.0 N","About 0.060 N","About 60 N"],"Coulomb's law gives F = kq1q2/r^2 = (8.99×10^9)(2.0×10^−6)(3.0×10^−6)/(0.30)^2 ≈ 0.60 N. The force depends on the product of both charges and falls off with the square of separation, not linearly.");
pq("U10","10.1","Electric Charge and Electric Force","3.A","If the distance between two fixed point charges is tripled, what happens to the magnitude of the electric force between them?","It becomes one-ninth as large.",["It becomes one-third as large.","It stays the same.","It becomes three times as large."],"Coulomb's law shows the force is inversely proportional to the square of the separation. Tripling r increases r^2 by a factor of 9, so the force is reduced to 1/9 of its original value.");
pq("U10","10.1","Electric Charge and Electric Force","1.A","Two small charged spheres repel each other when brought near one another. Which statement about their charges is best supported?","The spheres carry the same sign of charge.",["The spheres must both carry positive charge specifically.","One sphere is charged and the other is perfectly neutral.","The spheres carry charges of opposite sign."],"Like charges repel and opposite charges attract. Observing repulsion alone establishes that the two charges share the same sign, but does not by itself reveal whether that sign is positive or negative.");

pq("U10","10.2","Conservation of Electric Charge and the Process of Charging","1.B","A neutral metal sphere is charged by conduction after briefly touching a positively charged rod and then separating from it. Compared with the rod's original charge, the sphere ends up with","some positive charge, while the rod keeps a reduced amount",["a full negative charge, while the rod becomes fully neutral","exactly the same amount of positive charge that remains on the rod","no charge at all, since conduction only transfers charge briefly"],"Charging by conduction transfers some like-sign charge (here, positive) from the rod to the sphere until they reach a shared potential. Total charge is conserved between the two objects, but it is redistributed, not duplicated or eliminated.");
pq("U10","10.2","Conservation of Electric Charge and the Process of Charging","3.B","A neutral conducting sphere is charged by induction using a nearby negatively charged rod, without the rod ever touching the sphere. After the sphere is grounded and then the ground connection and rod are removed, the sphere ends up","positively charged, since electrons were repelled away through the ground connection",["negatively charged, since electrons were attracted onto the sphere from the ground","neutral, since induction never permanently changes an object's total charge","charged with the same charge sign as the inducing rod"],"The negative rod repels the sphere's mobile electrons; grounding lets those repelled electrons flow away to the ground. Removing the ground connection and then the rod traps the sphere with a net positive charge.");
pq("U10","10.2","Conservation of Electric Charge and the Process of Charging","2.B","An isolated system contains three point charges: +4.0 μC, −7.0 μC, and an unknown charge q. If the system's total charge is measured to be −5.0 μC, what is q?","−2.0 μC",["+2.0 μC","−16.0 μC","+16.0 μC"],"Conservation of charge requires the sum of all charges to equal the total: 4.0 + (−7.0) + q = −5.0, so q = −5.0 − (4.0 − 7.0) = −5.0 − (−3.0) = −2.0 μC.");

pq("U10","10.3","Electric Fields","2.A","What is the magnitude of the electric field at a point 0.50 m from a point charge of 4.0×10^−6 C?","About 1.44×10^5 N/C",["About 7.2×10^4 N/C","About 2.9×10^5 N/C","About 1.44×10^4 N/C"],"The field of a point charge is E = kq/r^2 = (8.99×10^9)(4.0×10^−6)/(0.50)^2 ≈ 1.44×10^5 N/C.");
pq("U10","10.3","Electric Fields","2.C","A positive test charge of 2.0×10^−6 C is placed at a point where the electric field has magnitude 5.0×10^4 N/C. What is the magnitude of the force on the test charge?","0.10 N",["2.5×10^10 N","0.010 N","1.0 N"],"Force on a charge in a field is F = qE = (2.0×10^−6)(5.0×10^4) = 0.10 N. The force points along the field direction for a positive test charge, and doubling either q or E would double this force.");
pq("U10","10.3","Electric Fields","1.A","Electric field lines are drawn around an isolated positive point charge. Which description correctly characterizes those field lines?","They point radially outward and are more closely spaced near the charge.",["They point radially inward toward the charge and are evenly spaced everywhere.","They form closed loops that circle around the charge indefinitely.","They point outward but are evenly spaced regardless of distance from the charge."],"Field lines around an isolated positive charge radiate outward, and their density represents field strength, which is greatest close to the charge and decreases with distance, so the lines are more closely spaced near the charge.");

pq("U10","10.4","Electric Potential Energy","2.B","Two point charges, q1 = 5.0×10^−6 C and q2 = −2.0×10^−6 C, are separated by 0.20 m. What is their electric potential energy?","About −0.45 J",["About +0.45 J","About −4.5 J","About −0.090 J"],"Electric potential energy of a pair of point charges is U = kq1q2/r = (8.99×10^9)(5.0×10^−6)(−2.0×10^−6)/0.20 ≈ −0.45 J. The negative sign reflects the attraction between opposite charges.");
pq("U10","10.4","Electric Potential Energy","3.A","Two charges of opposite sign start far apart and are allowed to move freely toward each other under their mutual attraction. As they get closer together, what happens to their electric potential energy?","It becomes more negative, decreasing.",["It becomes more positive, increasing.","It stays constant at zero throughout.","It first decreases, then increases back to zero."],"For opposite charges, U = kq1q2/r is negative and grows more negative as r decreases, since the charges attract and potential energy is converted into kinetic energy as they approach each other.");
pq("U10","10.4","Electric Potential Energy","2.D","An external agent does 3.0×10^−4 J of work to slowly move a positive charge from one point to another against the electric force, with no change in kinetic energy. What is the resulting change in the system's electric potential energy?","+3.0×10^−4 J",["−3.0×10^−4 J","0 J","+6.0×10^−4 J"],"When an external agent does work against the electric force with no change in kinetic energy, that work is stored as electric potential energy, so ΔU equals the work done by the external agent, +3.0×10^−4 J.");

pq("U10","10.5","Electric Potential","2.A","What is the electric potential at a point 0.30 m from an isolated point charge of 6.0×10^−6 C?","About 1.8×10^5 V",["About 9.0×10^4 V","About 3.6×10^5 V","About 1.8×10^4 V"],"Electric potential from a point charge is V = kq/r = (8.99×10^9)(6.0×10^−6)/0.30 ≈ 1.8×10^5 V.");
pq("U10","10.5","Electric Potential","3.B","A charge of 3.0×10^−6 C moves from a location at 200 V to a location at 500 V. How much work is done against the electric field by whatever moves the charge, assuming no change in kinetic energy?","9.0×10^−4 J",["9.0×10^−4 C·V, which is not a unit of work","3.0×10^−4 J","1.5×10^−3 J"],"Work done against the field equals qΔV = (3.0×10^−6)(500 − 200) = 9.0×10^−4 J, and volts times coulombs correctly gives joules, a unit of energy.");
pq("U10","10.5","Electric Potential","1.B","A charged conducting sphere in electrostatic equilibrium has its entire surface at the same electric potential. What can be concluded about points along that equipotential surface?","No work is needed to move a charge between points on the surface.",["A large amount of work is required to move a charge anywhere on the surface.","The electric field must point along the surface at every point.","The electric field must be zero everywhere just outside the surface."],"Because potential does not change along an equipotential surface, moving a charge between any two points on it requires zero net work. The field is perpendicular to, not along, an equipotential surface, and is nonzero just outside a charged conductor.");

pq("U10","10.6","Capacitors","2.A","A capacitor with capacitance 4.0×10^−6 F is connected to a 12 V battery. What charge accumulates on the capacitor?","4.8×10^−5 C",["3.0×10^−7 C","4.8×10^−7 C","48 C"],"Capacitor charge is given by Q = CV = (4.0×10^−6)(12) = 4.8×10^−5 C. Charge stored is directly proportional to the applied voltage for a fixed capacitance, unlike the energy stored, which scales with V^2.");
pq("U10","10.6","Capacitors","2.C","Using the same 4.0×10^−6 F capacitor charged to 12 V, how much energy is stored in the capacitor?","About 2.9×10^−4 J",["About 5.8×10^−4 J","About 4.8×10^−5 J","About 1.4×10^−4 J"],"Stored energy is U = (1/2)CV^2 = (1/2)(4.0×10^−6)(12)^2 = (1/2)(4.0×10^−6)(144) ≈ 2.9×10^−4 J.");
pq("U10","10.6","Capacitors","3.C","A parallel-plate capacitor's plate separation is doubled while the plate area and the charge on the plates are held fixed. What happens to the capacitance and the stored energy?","Capacitance is halved, and stored energy doubles.",["Capacitance doubles, and stored energy is halved.","Both capacitance and stored energy stay the same.","Capacitance is halved, and stored energy is also halved."],"Since C = ε0A/d, doubling d halves C. With Q held fixed, U = Q^2/(2C), so halving C doubles the stored energy for the same charge.");

pq("U10","10.7","Conservation of Electric Energy","2.D","A proton (charge +e) is released from rest and accelerates through a potential difference of 1000 V in vacuum. Using the work-energy theorem, what determines its final kinetic energy?","KE = qΔV, charge times the potential difference it moves through.",["KE = V/q, so kinetic energy is potential divided by charge.","KE depends only on the proton's initial position, not on the potential difference.","KE cannot be determined without knowing the exact path the proton follows."],"By conservation of energy, the electric potential energy lost as the proton accelerates converts entirely into kinetic energy, so KE = qΔV. Electric potential energy depends only on position (start and end points), not on the path taken.");
pq("U10","10.7","Conservation of Electric Energy","3.A","An electron moves from a region of lower electric potential to a region of higher electric potential, gaining kinetic energy as it does so. What does this reveal about the electron's charge?","This is consistent with the electron's negative charge, which loses potential energy as potential increases.",["The result shows the electron must actually behave as if positively charged in this situation.","The result violates conservation of energy for any charged particle.","The result is only possible if an external nonconservative force also acts on the electron."],"Electric potential energy is U = qV. For a negative charge, U decreases as V increases, so moving toward higher potential lowers U and correspondingly raises KE, consistent with the electron's actual negative charge and with energy conservation.");

// --------------------------------------------------------------------------
// Unit 11: Electric Circuits (8 topics)
// --------------------------------------------------------------------------
pq("U11","11.1","Electric Current","1.A","Which statement correctly describes conventional electric current in a simple wire circuit?","It is the direction positive charge would flow, though electrons are the actual carriers.",["It is defined only as the actual direction electrons move through the wire.","It exists in circuits that contain a capacitor, but not in a purely resistive circuit.","It flows in both directions simultaneously in a simple DC circuit."],"Conventional current is defined as the direction positive charge carriers would move. In an ordinary metal wire, the actual charge carriers are negatively charged electrons drifting in the opposite direction.");
pq("U11","11.1","Electric Current","2.A","A wire carries a steady current of 2.0 A. How much charge passes a cross-section of the wire in 10 s?","20 C",["0.20 C","5.0 C","200 C"],"Current is charge per unit time, I = ΔQ/Δt, so ΔQ = IΔt = (2.0)(10) = 20 C. A steady 2.0 A current means 2.0 coulombs of charge cross any cross-section of the wire during every second that passes.");
pq("U11","11.1","Electric Current","3.A","A metal wire's cross-sectional area is decreased while the same current continues to flow through it. What happens to the average drift speed of the charge carriers?","It increases, since the same current passes through a smaller area.",["It decreases, since a narrower wire slows individual carriers.","It stays exactly the same regardless of the wire's cross-sectional area.","It becomes zero, since current cannot flow through a narrower wire."],"For fixed current and carrier density, I = nqAv_d shows drift speed v_d must increase to compensate for a smaller cross-sectional area A while keeping the same current I.");

pq("U11","11.2","Simple Circuits","1.B","In a simple circuit with a single battery and a single resistor connected in a complete loop, what is required for current to flow continuously?","A closed conducting path from one battery terminal to the other.",["A capacitor placed somewhere in the loop to store the moving charge.","An open switch left in the circuit at all times.","Two separate batteries connected to opposite ends of the resistor."],"Current requires a closed conducting loop from one battery terminal, through the circuit elements, and back to the other terminal. An open switch interrupts this path and stops current flow.");
pq("U11","11.2","Simple Circuits","2.B","A single resistor is connected directly across an ideal 9.0 V battery with no other circuit elements. If the resistor has resistance 3.0 Ω, what current flows through it?","3.0 A",["0.33 A","27 A","6.0 A"],"By Ohm's law, I = V/R = 9.0/3.0 = 3.0 A for this simple one-resistor loop. With only one resistor and an ideal battery, the full 9.0 V drop occurs across that single resistor, driving this current.");
pq("U11","11.2","Simple Circuits","3.B","A student adds a second identical resistor in series with an existing single-resistor circuit connected to the same battery. What happens to the total circuit resistance and the current supplied by the battery?","Total resistance increases, and the current supplied by the battery decreases.",["Total resistance decreases, and the current supplied by the battery increases.","Total resistance stays the same, and the current stays the same.","Total resistance increases, but the current supplied by the battery also increases."],"Adding a resistor in series increases the total resistance of the loop. Since the battery's voltage is unchanged, I = V/R_total shows the current supplied by the battery must decrease.");

pq("U11","11.3","Resistance, Resistivity, and Ohm's Law","2.A","A wire has resistance 8.0 Ω. What current flows through it when a potential difference of 24 V is applied across its ends?","3.0 A",["0.33 A","192 A","16 A"],"Ohm's law gives I = V/R = 24/8.0 = 3.0 A. Current through a resistor is directly proportional to the voltage across it and inversely proportional to its resistance, for a fixed ohmic resistor.");
pq("U11","11.3","Resistance, Resistivity, and Ohm's Law","3.A","A metal wire is replaced with a new wire of the same material and cross-sectional area but twice the length. How does the new wire's resistance compare to the original?","It is twice as large.",["It is half as large.","It is four times as large.","It stays the same."],"Resistance is given by R = ρL/A, which is directly proportional to length for fixed resistivity and cross-sectional area. Doubling the length doubles the resistance.");
pq("U11","11.3","Resistance, Resistivity, and Ohm's Law","3.B","Two wires are made of different materials but have identical length and cross-sectional area. Wire X has a higher resistivity than wire Y. Which statement correctly compares their resistances?","Wire X has the greater resistance, proportional to its higher resistivity.",["Wire X has the smaller resistance, since resistivity and resistance vary inversely.","Both wires must have identical resistance regardless of resistivity.","Resistivity does not affect resistance unless the wires carry different currents."],"From R = ρL/A, resistance is directly proportional to resistivity when length and cross-sectional area are fixed. The higher-resistivity wire X therefore has the greater resistance.");

pq("U11","11.4","Electric Power","2.A","A resistor carries a current of 2.0 A while dissipating power according to P = I^2R, where R = 5.0 Ω. How much power does the resistor dissipate?","20 W",["10 W","2.5 W","50 W"],"Power dissipated in a resistor is P = I^2R = (2.0)^2(5.0) = (4.0)(5.0) = 20 W. Because current is squared in this formula, doubling the current would quadruple the dissipated power, not merely double it.");
pq("U11","11.4","Electric Power","2.B","A device is rated for 12 V and draws a current of 3.0 A while operating. Using P = VI, how much power does it consume?","36 W",["4.0 W","15 W","9.0 W"],"Electric power delivered to a device is P = VI = (12)(3.0) = 36 W. This is the general power formula for any circuit element, and it reduces to P = I^2R or P = V^2/R for a purely resistive device.");
pq("U11","11.4","Electric Power","3.C","Two resistors, R1 and R2 = 2R1, carry the same current. How does the power dissipated in R2 compare with the power dissipated in R1?","R2 dissipates twice as much power as R1.",["R2 dissipates half as much power as R1.","R2 dissipates four times as much power as R1.","Both resistors dissipate the same power regardless of resistance."],"With the same current through both, P = I^2R is directly proportional to resistance. Since R2 = 2R1, R2 dissipates twice the power of R1 for the same current.");

pq("U11","11.5","Compound Direct Current (DC) Circuits","2.C","In a circuit, a 4.0 Ω resistor is in series with a parallel combination of a 6.0 Ω resistor and a 3.0 Ω resistor, all connected to a 12 V ideal battery. What is the total current supplied by the battery?","2.0 A",["3.0 A","1.0 A","4.0 A"],"The parallel section has equivalent resistance 1/(1/6.0+1/3.0) = 2.0 Ω. Total resistance is 4.0+2.0 = 6.0 Ω, so total current is I = V/R = 12/6.0 = 2.0 A.");
pq("U11","11.5","Compound Direct Current (DC) Circuits","2.D","Using the same circuit as above (4.0 Ω in series with a parallel 6.0 Ω and 3.0 Ω combination on a 12 V battery), what is the current through the 3.0 Ω resistor?","About 1.33 A",["2.0 A","0.67 A","1.0 A"],"The parallel combination's voltage equals total current times its equivalent resistance: V_parallel = (2.0 A)(2.0 Ω) = 4.0 V. Current through the 3.0 Ω branch is then 4.0/3.0 ≈ 1.33 A.");
pq("U11","11.5","Compound Direct Current (DC) Circuits","3.A","Two resistors are connected in parallel across the same ideal battery. Which statement about them is correct?","Both resistors have the same voltage across them, equal to the battery's voltage.",["Both resistors carry exactly the same current regardless of their resistance values.","The equivalent resistance of the pair is always greater than either individual resistance.","No current can flow through either resistor unless they have equal resistance."],"Parallel elements share the same two connection points, so they share the same voltage, equal to the battery voltage for an ideal battery. Their currents can differ if their resistances differ, and parallel equivalent resistance is always less than the smallest individual resistance.");

pq("U11","11.6","Kirchhoff's Loop Rule","2.B","A single-loop circuit has a 9.0 V battery in series with three resistors: 2.0 Ω, 3.0 Ω, and 4.0 Ω. What is the current in the loop?","1.0 A",["9.0 A","0.11 A","4.5 A"],"Kirchhoff's loop rule for this series loop gives 9.0 = I(2.0+3.0+4.0) = I(9.0), so I = 1.0 A.");
pq("U11","11.6","Kirchhoff's Loop Rule","2.C","In the same loop (9.0 V battery, resistors 2.0 Ω, 3.0 Ω, 4.0 Ω in series, current 1.0 A), what is the voltage drop across the 3.0 Ω resistor?","3.0 V",["9.0 V","0.33 V","1.0 V"],"By Ohm's law, the voltage drop across a series resistor is V = IR = (1.0)(3.0) = 3.0 V, consistent with Kirchhoff's loop rule requiring the sum of all voltage drops to equal the 9.0 V source.");
pq("U11","11.6","Kirchhoff's Loop Rule","3.A","Kirchhoff's loop rule states that the sum of voltage changes around any closed loop in a circuit must equal zero. This rule is a direct consequence of which physical principle?","Conservation of energy: returning to the start yields zero net potential-energy change.",["Conservation of charge, since charge cannot be created or destroyed in a loop.","Conservation of momentum, since current-carrying charges have momentum.","Newton's third law, applied to the forces between circuit elements."],"Electric potential is a form of potential energy per charge. A charge that traverses a closed loop and returns to its starting point must have zero net change in potential energy, which is an expression of energy conservation.");

pq("U11","11.7","Kirchhoff's Junction Rule","2.A","At a circuit junction, a current of 3.0 A flows in, and two currents flow out: 1.5 A along one branch and an unknown current I along the other branch. What is I?","1.5 A",["3.0 A","4.5 A","1.0 A"],"Kirchhoff's junction rule requires total current into a junction to equal total current out: 3.0 = 1.5 + I, so I = 1.5 A.");
pq("U11","11.7","Kirchhoff's Junction Rule","3.A","Kirchhoff's junction rule, which requires total current into a junction to equal total current out, is a direct consequence of which physical principle?","Conservation of charge, since charge cannot accumulate at a steady-state junction.",["Conservation of energy, since current carries kinetic energy through the junction.","Newton's second law applied to the moving charge carriers.","Conservation of angular momentum for charges passing through the junction."],"In steady-state current flow, charge cannot build up or disappear at a junction, so the total charge entering per second must equal the total charge leaving per second — a statement of charge conservation.");

pq("U11","11.8","Resistor-Capacitor (RC) Circuits","2.A","A resistor with R = 2000 Ω is connected in series with a capacitor of C = 5.0×10^−6 F. What is the time constant of this RC circuit?","0.010 s",["1.0×10^−2 Ω·F, which is not a time","0.10 s","1.0×10^4 s"],"The time constant of a series RC circuit is τ = RC = (2000)(5.0×10^−6) = 0.010 s, and ohms times farads correctly gives seconds.");
pq("U11","11.8","Resistor-Capacitor (RC) Circuits","3.B","Immediately after a fully charged capacitor begins discharging through a resistor, what happens to the current in the circuit as time passes?","The current starts at maximum and decreases smoothly toward zero.",["The current starts at zero and increases smoothly toward a maximum.","The current remains perfectly constant throughout the discharge.","The current oscillates periodically between positive and negative values."],"During RC discharge, both the capacitor's charge and the circuit current decay exponentially from their initial values toward zero, with no oscillation in a simple resistor-capacitor loop.");

// --------------------------------------------------------------------------
// Unit 12: Magnetism and Electromagnetism (4 topics)
// --------------------------------------------------------------------------
pq("U12","12.1","Magnetic Fields","2.A","A long straight wire carries a current of 10 A. Using μ0 = 4π×10^−7 T·m/A, what is the magnitude of the magnetic field at a perpendicular distance of 0.020 m from the wire?","1.0×10^−4 T",["5.0×10^−5 T","2.0×10^−4 T","1.0×10^−2 T"],"The field around a long straight current-carrying wire is B = μ0I/(2πr) = (4π×10^−7)(10)/(2π×0.020) = 1.0×10^−4 T.");
pq("U12","12.1","Magnetic Fields","1.A","A long straight wire carries current directly upward through a horizontal table. Using the right-hand rule, what is the direction of the magnetic field it creates at a point directly to the east of the wire, at the same height?","The field points north at that point, circling the wire counterclockwise from above.",["The field points directly away from the wire, radially outward to the east.","The field points straight down toward the table at that point.","The field points to the south at that point, circling the wire clockwise when viewed from above."],"Pointing the right thumb in the direction of conventional current (upward) curls the fingers in the field's direction, producing a counterclockwise field pattern when viewed from above; directly east of the wire, that field points north.");
pq("U12","12.1","Magnetic Fields","3.A","Doubling the current in a long straight wire while keeping distance from the wire fixed does what to the magnetic field at that point?","It doubles the magnetic field magnitude.",["It quadruples the magnetic field magnitude.","It leaves the magnetic field magnitude unchanged.","It halves the magnetic field magnitude."],"Since B = μ0I/(2πr), magnetic field magnitude is directly proportional to current at fixed distance, so doubling I doubles B.");

pq("U12","12.2","Magnetism and Moving Charges","2.A","A charged particle with charge 1.6×10^−19 C moves at 2.0×10^6 m/s perpendicular to a magnetic field of 0.50 T. What is the magnitude of the magnetic force on the particle?","1.6×10^−13 N",["3.2×10^−13 N","8.0×10^−14 N","1.6×10^−19 N"],"The magnetic force on a moving charge is F = qvB (for velocity perpendicular to the field) = (1.6×10^−19)(2.0×10^6)(0.50) = 1.6×10^−13 N.");
pq("U12","12.2","Magnetism and Moving Charges","1.B","A positive charge moves to the right through a magnetic field that points into the page. Using F = qv×B, what is the direction of the magnetic force on the charge at that instant?","Upward, in the plane of the page.",["Downward, in the plane of the page.","Directly into the page, parallel to the field.","Directly out of the page, opposite the field."],"With velocity to the right and field into the page, the right-hand rule for v×B (fingers point right, curl into the page) gives a cross product pointing upward in the plane of the page for a positive charge.");
pq("U12","12.2","Magnetism and Moving Charges","3.B","A charged particle moves in a circular path perpendicular to a uniform magnetic field because the magnetic force provides centripetal force. If the particle's speed is doubled while the field strength stays the same, what happens to the radius of its circular path?","The radius doubles.",["The radius stays the same.","The radius is cut in half.","The radius quadruples."],"Setting magnetic force equal to centripetal force, qvB = mv^2/r, gives r = mv/(qB). With m, q, and B fixed, radius is directly proportional to speed, so doubling v doubles r.");
pq("U12","12.2","Magnetism and Moving Charges","2.B","A charged particle moves exactly parallel to a uniform magnetic field, rather than perpendicular to it. What is the magnitude of the magnetic force on the particle in this case?","Zero, since F = qvB sinθ and θ = 0° between velocity and field.",["Maximum, since a parallel field always produces the greatest possible force.","Equal to qvB, the same as when velocity is perpendicular to the field.","It cannot be found from the angle alone; it also depends on the particle's charge sign."],"The magnetic force magnitude is F = qvB sinθ, where θ is the angle between velocity and field. When the particle moves parallel to the field, θ = 0°, so sinθ = 0 and the force is zero.");

pq("U12","12.3","Magnetism and Current-Carrying Wires","2.A","A straight wire segment of length 0.40 m carries a current of 5.0 A perpendicular to a uniform magnetic field of 0.30 T. What is the magnitude of the magnetic force on the wire segment?","0.60 N",["1.2 N","0.075 N","6.0 N"],"The force on a current-carrying wire perpendicular to a field is F = BIL = (0.30)(5.0)(0.40) = 0.60 N.");
pq("U12","12.3","Magnetism and Current-Carrying Wires","3.A","Two long, straight, parallel wires carry current in the same direction as each other. What is the nature of the magnetic force between them?","The wires attract each other.",["The wires repel each other.","There is no magnetic force between them.","The force alternates between attraction and repulsion over time."],"Each current-carrying wire creates a magnetic field that exerts a force on the other wire's current. Parallel wires carrying current in the same direction attract; if the currents were in opposite directions, the wires would repel.");
pq("U12","12.3","Magnetism and Current-Carrying Wires","1.A","A horizontal current-carrying wire is oriented parallel to a uniform magnetic field rather than at an angle to it. What magnetic force does the wire experience from that field?","Zero force, since a parallel current feels no magnetic force.",["The maximum possible force for that current and field strength.","A force perpendicular to both the wire and the field, but nonzero.","A force directed along the wire's own length."],"Force on a current-carrying wire is F = BIL sinθ, where θ is the angle between the current direction and the field. A wire oriented parallel to the field has θ = 0°, giving zero magnetic force.");

pq("U12","12.4","Electromagnetic Induction and Faraday's Law","2.A","A coil of 100 turns experiences a change in magnetic flux of 5.0×10^−3 Wb through each turn over a time interval of 0.20 s. Using Faraday's law, what is the magnitude of the induced EMF?","2.5 V",["0.025 V","25 V","1.0×10^−3 V"],"Faraday's law gives EMF = N(ΔΦ/Δt) = (100)(5.0×10^−3)/(0.20) = 2.5 V. Each of the coil's 100 turns contributes to the induced EMF, so more turns or a faster flux change both increase the result.");
pq("U12","12.4","Electromagnetic Induction and Faraday's Law","3.B","A bar magnet is pushed north-pole-first toward a stationary conducting loop, inducing a current in the loop. According to Lenz's law, what is true about the induced current's magnetic field near the approaching magnet?","It opposes the increasing flux, creating a field that repels the approaching north pole.",["It reinforces the increasing flux, creating a field that attracts the approaching north pole.","It has no defined direction, since Lenz's law only predicts the current's magnitude.","It depends mainly on the loop's resistance rather than on the direction of the magnet's motion."],"Lenz's law states that induced current opposes the change in flux that produces it. As the north pole approaches and flux through the loop increases, the induced current creates a field that opposes that increase, which repels the incoming north pole.");
pq("U12","12.4","Electromagnetic Induction and Faraday's Law","2.B","A single loop of wire with area 0.050 m^2 sits in a magnetic field that increases uniformly from 0.20 T to 0.60 T over 0.10 s, with the field always perpendicular to the loop. What is the magnitude of the induced EMF in the loop?","0.20 V",["0.020 V","2.0 V","0.040 V"],"Flux is Φ = BA, so ΔΦ = (ΔB)A = (0.60−0.20)(0.050) = 0.020 Wb. EMF = ΔΦ/Δt = 0.020/0.10 = 0.20 V for this single-turn loop.");
pq("U12","12.4","Electromagnetic Induction and Faraday's Law","3.A","A conducting loop sits in a magnetic field that is constant in time, and the loop does not move, rotate, or change shape. What induced EMF does Faraday's law predict for this loop?","Zero EMF, since the magnetic flux through the loop is not changing.",["A constant nonzero EMF proportional to the field strength itself.","An EMF that depends on the field strength but not on the loop's area.","An oscillating EMF, since all magnetic fields produce time-varying induction."],"Faraday's law relates induced EMF to the rate of change of magnetic flux, EMF = −N(ΔΦ/Δt). With a constant field and an unchanging, stationary loop, flux does not change over time, so the induced EMF is zero.");

// --------------------------------------------------------------------------
// Unit 13: Geometric Optics (4 topics)
// --------------------------------------------------------------------------
pq("U13","13.1","Reflection","1.A","A light ray strikes a flat mirror at an angle of 40° measured from the normal to the mirror surface. At what angle from the normal does the reflected ray leave the mirror?","40°",["50°","80°","20°"],"The law of reflection states that the angle of incidence equals the angle of reflection, both measured from the normal, so the reflected ray also leaves at 40° from the normal.");
pq("U13","13.1","Reflection","1.B","A rough, unpolished surface reflects a parallel beam of light so that the rays scatter in many different directions rather than remaining parallel. This is best described as","diffuse reflection, caused by microscopic irregularities in the surface",["specular reflection, which by definition scatters light randomly","refraction, since the light bends while leaving the surface","total internal reflection, which requires light traveling inside a denser medium"],"Diffuse reflection occurs when a surface's microscopic irregularities reflect each individual ray according to the law of reflection locally, but the varying local surface angles scatter the overall beam in many directions. Specular reflection, by contrast, keeps parallel rays parallel.");
pq("U13","13.1","Reflection","3.A","An object is placed in front of a flat (plane) mirror. Which statement about the image correctly describes its properties?","The image is virtual, upright, same-sized, and as far behind as the object is in front.",["The image is real, inverted, and can be projected onto a screen placed behind the mirror.","The image is virtual but always smaller than the object.","The image distance behind the mirror depends on the object's height, not its distance from the mirror."],"A plane mirror always forms a virtual, upright, same-size image located behind the mirror at a distance equal to the object's distance in front of it, regardless of the object's height.");

pq("U13","13.2","Images Formed by Mirrors","2.A","A concave mirror has a focal length of 15 cm. An object is placed 30 cm in front of the mirror. Using 1/f = 1/do + 1/di, what is the image distance?","30 cm",["15 cm","45 cm","10 cm"],"Solving 1/di = 1/f − 1/do = 1/15 − 1/30 = 1/30 gives di = 30 cm, a real image formed on the same side as the object.");
pq("U13","13.2","Images Formed by Mirrors","2.B","Using the same concave mirror (f = 15 cm) with the object now at 30 cm and image at 30 cm, what is the magnification of the image?","−1, meaning the image is the same size but inverted.",["+1, meaning the image is the same size and upright.","−2, meaning the image is twice as large and inverted.","+0.5, meaning the image is half as large and upright."],"Magnification is m = −di/do = −30/30 = −1. The negative sign indicates an inverted image, and the magnitude of 1 indicates the image is the same size as the object.");
pq("U13","13.2","Images Formed by Mirrors","2.C","A concave mirror with focal length 20 cm has an object placed only 10 cm in front of it, inside the focal length. What kind of image results?","A virtual, upright, enlarged image located behind the mirror.",["A real, inverted, reduced image located in front of the mirror.","A real, upright image located exactly at the mirror's surface.","No image forms at all when the object is inside the focal length."],"Solving 1/di = 1/f − 1/do = 1/20 − 1/10 = −1/20 gives a negative image distance, indicating a virtual image behind the mirror; for a concave mirror with the object inside the focal length, this image is upright and enlarged.");
pq("U13","13.2","Images Formed by Mirrors","3.B","A convex (diverging) mirror is used to form an image of an object placed in front of it. Which statement about the image is always true, regardless of the object's distance from the mirror?","The image is virtual, upright, and reduced in size.",["The image is real and can always be projected onto a screen.","The image is inverted whenever the object is farther than the focal length.","The image size depends mainly on the mirror's radius rather than on object distance."],"A convex mirror has a virtual focal point behind the mirror, so it always produces a virtual, upright, reduced image for any real object position, unlike a concave mirror whose image type depends on object distance.");

pq("U13","13.3","Refraction","2.A","Light traveling in air (n = 1.00) strikes a glass surface (n = 1.50) at an angle of 30° from the normal. Using Snell's law, what is the angle of refraction inside the glass?","About 19.5°",["About 45.0°","About 30.0°","About 60.0°"],"Snell's law gives n1 sinθ1 = n2 sinθ2, so sinθ2 = (1.00)(sin30°)/1.50 = 0.333, and θ2 = sin^−1(0.333) ≈ 19.5°.");
pq("U13","13.3","Refraction","1.A","A light ray travels from air into a denser transparent medium, striking the boundary at a nonzero angle from the normal. What happens to the ray's direction as it enters the denser medium?","It bends toward the normal, since light slows down entering a higher-index medium.",["It bends away from the normal, since light speeds up entering a denser medium.","It continues in a perfectly straight line with no change in direction.","It reflects entirely back into the original medium instead of refracting."],"When light enters an optically denser medium (higher index of refraction), its speed decreases, and Snell's law requires the ray to bend toward the normal to satisfy n1 sinθ1 = n2 sinθ2 with n2 > n1.");
pq("U13","13.3","Refraction","2.C","Light traveling inside glass (n = 1.50) approaches a glass-to-air boundary. What is the critical angle beyond which total internal reflection occurs?","About 41.8°",["About 48.2°","About 30.0°","About 60.0°"],"The critical angle satisfies sinθc = n2/n1 = 1.00/1.50 = 0.667, giving θc = sin^−1(0.667) ≈ 41.8°. At angles of incidence beyond this, the ray is totally internally reflected rather than refracted.");
pq("U13","13.3","Refraction","3.A","A medium's index of refraction is defined as n = c/v, where c is the speed of light in vacuum and v is the speed of light in that medium. A material with a very high index of refraction has light traveling through it","much more slowly than in vacuum, since large n means small v",["much faster than in vacuum, since a large n corresponds to a large v","at exactly the speed of light regardless of the medium","in a direction opposite to its direction in vacuum"],"Since n = c/v, a larger index of refraction n corresponds to a smaller speed v for a fixed speed of light c in vacuum, meaning light travels more slowly through a high-index medium.");

pq("U13","13.4","Images Formed by Lenses","2.A","A converging lens has a focal length of 10 cm. An object is placed 25 cm in front of the lens. Using 1/f = 1/do + 1/di, what is the image distance?","About 16.7 cm",["About 6.7 cm","About 35 cm","About 25 cm"],"Solving 1/di = 1/f − 1/do = 1/10 − 1/25 = 0.10 − 0.04 = 0.06 gives di ≈ 16.7 cm, a real image on the opposite side of the lens from the object.");
pq("U13","13.4","Images Formed by Lenses","2.B","For the same converging lens (f = 10 cm, do = 25 cm, di ≈ 16.7 cm), what is the magnification, and what does its sign indicate about the image orientation?","About −0.67, showing an inverted image relative to the object.",["About +0.67, indicating an upright image relative to the object.","About −1.5, indicating an inverted, enlarged image.","About +1.5, indicating an upright, enlarged image."],"Magnification is m = −di/do = −16.7/25 ≈ −0.67. The negative sign indicates the image is inverted, and the magnitude less than 1 indicates the image is reduced compared with the object.");
pq("U13","13.4","Images Formed by Lenses","3.B","A diverging lens is used to view an object at any real object distance. Which statement correctly describes the image it always forms?","The image is always virtual, upright, and reduced in size, regardless of object distance.",["The image is always real and can be projected on a screen behind the lens.","The image is virtual for close objects but real for distant objects.","The image is roughly the same size as the object across most distances."],"A diverging lens has a negative focal length, and solving the lens equation for any positive object distance always yields a negative image distance, corresponding to a virtual, upright, reduced image on the same side as the object.");
pq("U13","13.4","Images Formed by Lenses","1.B","Two thin lenses are compared: lens A is converging with a positive focal length, and lens B is diverging with a negative focal length. A parallel beam of light traveling along the optical axis strikes each lens. What happens to the beam after passing through each lens?","Lens A converges the beam; lens B makes it diverge from a virtual focal point.",["The beam converges after both lens A and lens B, since both are thin lenses.","The beam spreads apart after both lens A and lens B, regardless of their focal length sign.","The beam remains perfectly parallel after passing through either lens."],"A converging lens bends parallel rays toward a real focal point on the far side of the lens, while a diverging lens spreads parallel rays apart so that they appear to originate from a virtual focal point on the near side.");

// --------------------------------------------------------------------------
// Unit 14: Waves, Sound, and Physical Optics (9 topics)
// --------------------------------------------------------------------------
pq("U14","14.1","Properties of Wave Pulses and Waves","2.A","A wave has frequency 250 Hz and wavelength 1.4 m. Using v = fλ, what is its speed?","350 m/s",["178.6 m/s","1.4 m/s","250 m/s"],"Wave speed is the product of frequency and wavelength: v = fλ = (250)(1.4) = 350 m/s. For a wave in a given medium, speed is normally fixed, so frequency and wavelength trade off inversely instead.");
pq("U14","14.1","Properties of Wave Pulses and Waves","1.A","In a transverse wave traveling along a stretched string, how does the motion of the string particles relate to the wave's direction of travel?","The particles move perpendicular to the direction the wave travels.",["The particles move parallel to the direction the wave travels.","The particles move in circles around the wave's direction of travel.","The particles do not move at all as the wave passes."],"A transverse wave is defined by particle motion perpendicular to the wave's propagation direction, unlike a longitudinal wave such as sound, where particles oscillate parallel to the direction of travel.");
pq("U14","14.1","Properties of Wave Pulses and Waves","3.A","A wave's amplitude is increased while its frequency and wavelength stay the same. What happens to the energy the wave transports?","The energy increases, since wave energy increases with amplitude.",["The energy stays exactly the same, since energy depends only on frequency.","The energy decreases, since larger amplitude spreads energy over more space.","The energy becomes undefined without knowing the medium's density."],"For mechanical waves, transported energy increases with amplitude (typically proportional to amplitude squared), independent of whether frequency and wavelength are held fixed.");

pq("U14","14.2","Periodic Waves","2.A","A periodic wave has a period of 0.0040 s. What is its frequency?","250 Hz",["0.0040 Hz","400 Hz","25 Hz"],"Frequency is the reciprocal of period: f = 1/T = 1/0.0040 = 250 Hz. A shorter period means more complete cycles occur every second, so period and frequency are always inversely related this way.");
pq("U14","14.2","Periodic Waves","2.B","A sound wave travels at 340 m/s and has a frequency of 425 Hz. What is its wavelength?","0.80 m",["144,500 m","1.25 m","0.40 m"],"Rearranging v = fλ gives λ = v/f = 340/425 = 0.80 m. Since the wave's speed through the medium is fixed here, a higher frequency corresponds to a proportionally shorter wavelength, and vice versa.");
pq("U14","14.2","Periodic Waves","3.A","A wave's frequency is tripled while its speed through the medium stays constant. What happens to its wavelength?","The wavelength becomes one-third as large.",["The wavelength triples.","The wavelength stays the same.","The wavelength becomes one-ninth as large."],"Since v = fλ and v is fixed, wavelength and frequency are inversely proportional. Tripling frequency reduces wavelength to one-third of its original value.");

pq("U14","14.3","Boundary Behavior of Waves and Polarization","1.A","A wave pulse traveling along a string reflects off an end that is rigidly fixed to a wall. What happens to the pulse's orientation upon reflection?","The reflected pulse is inverted, flipped relative to the incoming pulse.",["The reflected pulse keeps the same orientation as the incoming pulse.","The reflected pulse splits into two pulses of half amplitude each.","The pulse is completely absorbed and no reflection occurs."],"A wave reflecting off a fixed (rigid) boundary undergoes a phase inversion, flipping the pulse's orientation, unlike reflection off a free end, which preserves orientation.");
pq("U14","14.3","Boundary Behavior of Waves and Polarization","3.A","Unpolarized light passes through an ideal polarizing filter. What is true about the light that emerges?","It becomes linearly polarized, oscillating along a single direction.",["It becomes completely blocked, since polarizers absorb all incoming light.","It remains unpolarized, since polarizers affect sound waves rather than light waves.","It becomes circularly polarized, rotating steadily as it travels."],"A polarizing filter transmits only the component of the electric field aligned with its transmission axis, producing linearly polarized light from an initially unpolarized beam.");
pq("U14","14.3","Boundary Behavior of Waves and Polarization","1.B","Why can transverse waves, such as light, be polarized, while ordinary longitudinal waves, such as sound in air, cannot?","Only transverse waves have a second oscillation direction perpendicular to travel.",["Longitudinal waves travel too slowly for polarization to occur.","Polarization only applies to waves that require no medium to travel through.","Transverse waves tend to have larger amplitude than longitudinal waves."],"Polarization refers to constraining the direction of oscillation perpendicular to a wave's travel direction. A longitudinal wave oscillates only along its direction of travel and has no perpendicular oscillation to restrict, so it cannot be polarized.");

pq("U14","14.4","Electromagnetic Waves","1.A","Which list correctly orders regions of the electromagnetic spectrum from lowest to highest frequency?","Radio waves, infrared, visible light, ultraviolet, X-rays",["X-rays, ultraviolet, visible light, infrared, radio waves","Visible light, radio waves, infrared, X-rays, ultraviolet","Infrared, visible light, radio waves, X-rays, ultraviolet"],"The electromagnetic spectrum increases in frequency (and decreases in wavelength) in the order radio, microwave, infrared, visible, ultraviolet, X-ray, and gamma ray.");
pq("U14","14.4","Electromagnetic Waves","2.B","A radio wave has a frequency of 1.0×10^6 Hz. Using c = 3.00×10^8 m/s, what is its wavelength?","300 m",["3.0×10^14 m","3.0×10^2 Hz, not a length","3.0 m"],"For electromagnetic waves, c = fλ, so λ = c/f = (3.00×10^8)/(1.0×10^6) = 300 m. All electromagnetic waves travel at the same speed c in vacuum, so their frequency alone fixes their wavelength.");
pq("U14","14.4","Electromagnetic Waves","3.A","Unlike mechanical waves such as sound, electromagnetic waves can travel through a vacuum. What does this reveal about how electromagnetic waves propagate?","They propagate through oscillating electric and magnetic fields, needing no material medium.",["They actually require an undetectable material medium that fills all of space.","They do not really travel through a vacuum, but appear to due to measurement limitations.","They propagate identically to sound waves, just at a much higher frequency."],"Electromagnetic waves consist of self-sustaining oscillating electric and magnetic fields that regenerate each other, allowing propagation without any material medium, unlike mechanical waves such as sound.");

pq("U14","14.5","The Doppler Effect","2.A","A sound source emitting 500 Hz moves toward a stationary observer at a speed such that the observed frequency increases. Using v_sound = 340 m/s and a source speed of 30 m/s, what frequency does the observer hear?","About 548 Hz",["About 459 Hz","About 500 Hz","About 570 Hz"],"For a source approaching a stationary observer, f' = f·v/(v−vs) = 500(340)/(340−30) ≈ 548 Hz, an increase from the emitted frequency.");
pq("U14","14.5","The Doppler Effect","2.B","Using the same source (500 Hz) and speed (30 m/s), but now moving away from the stationary observer instead of toward it, what frequency does the observer hear?","About 459 Hz",["About 548 Hz","About 500 Hz","About 430 Hz"],"For a source receding from a stationary observer, f' = f·v/(v+vs) = 500(340)/(340+30) ≈ 459 Hz, a decrease from the emitted frequency.");
pq("U14","14.5","The Doppler Effect","1.A","An observer stands still as an ambulance with its siren sounding first approaches and then passes and moves away. How does the perceived pitch of the siren change during this event?","The pitch is higher while approaching, then drops lower after passing.",["The pitch stays exactly the same throughout, since the siren's true frequency never changes.","The pitch is lower while approaching, then rises higher after the ambulance passes.","The pitch continuously increases the entire time, both approaching and receding."],"The Doppler effect raises the perceived frequency above the source's true frequency while the source approaches, and lowers it below the true frequency once the source is receding, producing the familiar high-to-low pitch drop as it passes.");

pq("U14","14.6","Wave Interference and Standing Waves","2.A","A string of length 1.2 m fixed at both ends supports waves at 240 m/s. What is the frequency of the third harmonic, using fn = nv/(2L)?","300 Hz",["100 Hz","200 Hz","600 Hz"],"For a string fixed at both ends, fn = nv/(2L). For n = 3: f3 = 3(240)/(2×1.2) = 720/2.4 = 300 Hz.");
pq("U14","14.6","Wave Interference and Standing Waves","2.C","A pipe closed at one end and open at the other has length 0.85 m, with sound speed 340 m/s. Using fn = nv/(4L) for odd n only, what is its fundamental frequency?","100 Hz",["200 Hz","400 Hz","50 Hz"],"For a pipe closed at one end, only odd harmonics exist and fn = nv/(4L). The fundamental (n = 1) is f1 = 340/(4×0.85) = 340/3.4 = 100 Hz.");
pq("U14","14.6","Wave Interference and Standing Waves","3.A","Two identical waves traveling in opposite directions along a string meet and momentarily overlap so that their displacements exactly cancel at every point. This is best described as","perfectly destructive interference, where the waves are out of phase",["constructive interference, since combined waves always add together","refraction, since the waves changed direction upon meeting","resonance, which requires a driving force at the natural frequency"],"Interference is destructive when overlapping waves are out of phase enough that their displacements partially or fully cancel; the extreme case of exact cancellation is perfectly destructive interference, distinct from constructive interference, refraction, or resonance.");
pq("U14","14.6","Wave Interference and Standing Waves","1.B","A standing wave pattern forms on a string fixed at both ends. What characterizes the points called nodes in this pattern?","Nodes are points that remain stationary at all times, with zero displacement.",["Nodes are points that oscillate with the maximum possible amplitude.","Nodes are points where the string is under zero tension.","Nodes are points that only exist at the fixed ends of the string."],"Nodes are locations of destructive interference between the two component traveling waves, resulting in zero displacement at all times; they occur at regular intervals along the string, not only at the fixed endpoints.");

pq("U14","14.7","Diffraction","3.A","A wave passes through a narrow opening whose width is comparable to the wave's wavelength. Compared with passing through a much wider opening, this narrow opening produces","more noticeable diffraction, spreading the wave into a wider range of angles",["less noticeable diffraction, since narrow openings block diffraction effects","identical diffraction, since opening width does not affect diffraction","no diffraction to speak of, since diffraction requires an opening wider than the wavelength"],"Diffraction becomes more pronounced as the opening's width approaches the size of the wavelength; a narrow opening comparable to λ spreads the wave into a much wider range of angles than a wide opening does.");
pq("U14","14.7","Diffraction","1.A","Sound waves are commonly heard around corners and obstacles more easily than visible light is seen around them. What best explains this difference?","Sound wavelengths are far larger than light's, giving it stronger diffraction.",["Sound is not actually a wave, so it is not subject to diffraction at all.","Visible light diffracts more strongly than sound under ordinary conditions.","Sound waves travel faster than light waves, allowing them to bend more easily."],"Diffraction effects depend on the wavelength relative to the obstacle or opening size. Audible sound has wavelengths on the order of centimeters to meters, much larger than typical obstacles, producing strong diffraction, while visible light's much shorter wavelength diffracts far less around ordinary objects.");

pq("U14","14.8","Double-Slit Interference and Diffraction Gratings","2.A","In a double-slit setup, the slit separation is 2.0×10^−4 m and the light's wavelength is 6.0×10^−7 m. Using d sinθ = mλ, what is sinθ for the second-order (m = 2) bright fringe?","0.0060",["0.0030","0.012","0.00030"],"Solving d sinθ = mλ for sinθ gives sinθ = mλ/d = (2)(6.0×10^−7)/(2.0×10^−4) = 0.0060. This small angle corresponds to the second-order bright fringe measured from the central maximum.");
pq("U14","14.8","Double-Slit Interference and Diffraction Gratings","3.B","In a double-slit interference pattern, the slit separation is decreased while the wavelength of light stays the same. What happens to the angular spacing between adjacent bright fringes?","The angular spacing increases.",["The angular spacing decreases.","The angular spacing stays exactly the same.","The bright fringes disappear entirely."],"From d sinθ = mλ, for fixed m and λ, sinθ is inversely proportional to d. Decreasing the slit separation increases the angle to each order, spreading the fringes farther apart.");
pq("U14","14.8","Double-Slit Interference and Diffraction Gratings","1.A","In Young's double-slit experiment, light passing through two closely spaced slits produces alternating bright and dark fringes on a screen. The bright fringes occur where","light waves from the two slits arrive in phase",["light from only one slit reaches the screen at all","light waves from the two slits arrive exactly out of phase","the screen absorbs light unevenly due to its material"],"Bright fringes in a double-slit pattern occur at locations where the path-length difference between the two slits is a whole number of wavelengths, so the waves arrive in phase and add constructively; dark fringes occur where they arrive out of phase.");

pq("U14","14.9","Thin-Film Interference","2.A","A thin film of material with index of refraction 1.33 has thickness 200 nm. For constructive interference with no net phase-shift difference between the two reflections, using 2nt = mλ, what wavelength (in nm) satisfies this condition for m = 1?","532 nm",["266 nm","150 nm","1064 nm"],"Solving 2nt = mλ for λ gives λ = 2nt/m = 2(1.33)(200)/1 = 532 nm for the m = 1 case. The factor of 2 accounts for light traveling down through the film's thickness and back up before recombining.");
pq("U14","14.9","Thin-Film Interference","3.A","A thin soap film in air has a higher index of refraction than the surrounding air on both sides. Why does light reflecting from the front surface of the film undergo a 180° phase shift, while light reflecting from the back surface (film-to-air) does not?","A phase shift occurs only when reflecting off a higher-index medium.",["A phase shift occurs at every reflection surface regardless of the surrounding media.","No phase shift ever occurs for reflections involving thin films.","The phase shift depends mainly on the film's thickness rather than on the surrounding indices."],"Reflection produces a 180° phase shift only when light reflects from a boundary where the index of refraction increases (low-to-high index). Reflection at the film's front surface (air-to-film) meets this condition, while reflection at the back surface (film-to-air) does not.");
pq("U14","14.9","Thin-Film Interference","1.B","A thin oil film on a wet road shows bands of different colors when viewed under white light. What causes these visible color bands?","Different wavelengths interfere constructively at different film thicknesses.",["The oil film absorbs all wavelengths except one fixed color everywhere.","The road surface beneath the film changes color depending on the water depth.","The colors result from the oil film's own pigment, unrelated to interference."],"Because the constructive-interference condition 2nt = mλ depends on both thickness t and wavelength λ, thickness variations across the film cause different wavelengths to interfere constructively at different locations, producing the observed rainbow of colors.");

// --------------------------------------------------------------------------
// Unit 15: Modern Physics (8 topics)
// --------------------------------------------------------------------------
pq("U15","15.1","Quantum Theory and Wave-Particle Duality","2.A","A photon has frequency 5.0×10^14 Hz. Using E = hf with h = 6.63×10^−34 J·s, what is its energy?","About 3.3×10^−19 J",["About 6.6×10^−34 J","About 1.5×10^19 J","About 6.6×10^−19 J"],"Photon energy is E = hf = (6.63×10^−34)(5.0×10^14) ≈ 3.3×10^−19 J. Photon energy depends only on frequency, not on the light's intensity, which instead governs how many photons arrive per second.");
pq("U15","15.1","Quantum Theory and Wave-Particle Duality","2.C","An electron moves at 2.0×10^6 m/s. Using the de Broglie relation λ = h/p with electron mass 9.11×10^−31 kg, what is its wavelength?","About 3.6×10^−10 m",["About 1.8×10^−10 m","About 7.3×10^−10 m","About 3.6×10^−19 m"],"The de Broglie wavelength is λ = h/p = h/(mv) = (6.63×10^−34)/[(9.11×10^−31)(2.0×10^6)] ≈ 3.6×10^−10 m.");
pq("U15","15.1","Quantum Theory and Wave-Particle Duality","3.A","In a double-slit experiment performed with individual electrons sent through one at a time, an interference pattern gradually builds up on the detector. What does this result demonstrate?","Electrons exhibit wave-like behavior, since each electron's wave passes through both slits.",["Electrons behave purely as classical particles, each traveling through exactly one slit.","Interference patterns can only form when many electrons pass through simultaneously.","The experiment shows electrons have no measurable wavelength in this setup."],"Even single electrons sent one at a time build up an interference pattern over many trials, showing each electron's associated wave interferes with itself, a hallmark of wave-particle duality rather than purely classical particle behavior.");

pq("U15","15.2","The Bohr Model of Atomic Structure","2.A","In the Bohr model of hydrogen, the energy of level n is En = −13.6/n^2 eV. What is the energy of the n = 2 level?","−3.4 eV",["−6.8 eV","−13.6 eV","−1.7 eV"],"Substituting n = 2 gives E2 = −13.6/(2)^2 = −13.6/4 = −3.4 eV. The negative sign shows the electron is bound to the nucleus, and higher n values give energies that are less negative, closer to zero.");
pq("U15","15.2","The Bohr Model of Atomic Structure","2.B","An electron in a hydrogen atom transitions from the n = 3 level (E3 = −1.51 eV) to the n = 2 level (E2 = −3.4 eV). What is the energy of the photon emitted in this transition?","About 1.89 eV",["About 4.91 eV","About −1.89 eV","About 1.51 eV"],"The photon energy equals the magnitude of the energy lost by the electron: |E3 − E2| = |−1.51 − (−3.4)| = 1.89 eV, emitted as the electron drops to the lower energy level.");
pq("U15","15.2","The Bohr Model of Atomic Structure","1.A","In the Bohr model, an electron bound to a hydrogen nucleus can only exist in certain specific, quantized energy levels rather than any arbitrary energy. What does this quantization directly explain about hydrogen's observed spectrum?","It explains hydrogen's emission and absorption at only specific wavelengths.",["It explains why hydrogen never emits or absorbs any electromagnetic radiation.","It explains why hydrogen's spectrum closely resembles other elements' spectra.","It explains why hydrogen atoms are electrically charged overall."],"Because only certain electron energy levels are allowed, transitions between them release or absorb photons of only certain specific energies, producing hydrogen's characteristic discrete spectral lines rather than a continuous spectrum.");

pq("U15","15.3","Emission and Absorption Spectra","1.A","A hot, low-density gas is viewed directly against a dark background. What type of spectrum does it typically produce?","A bright-line emission spectrum, with bright lines against a dark background.",["A continuous spectrum with no gaps, similar to a hot solid object.","A dark-line absorption spectrum, with dark lines against a bright background.","No spectrum at all, since gases cannot emit or absorb light."],"An excited, low-density gas emits light only at the specific wavelengths corresponding to its allowed electron transitions, producing a bright-line emission spectrum against an otherwise dark background.");
pq("U15","15.3","Emission and Absorption Spectra","1.B","White light passes through a cool, low-density gas before reaching a detector. Compared with the original white-light spectrum, what does the detector observe?","A continuous spectrum with dark lines at absorbed wavelengths.",["A continuous spectrum completely unchanged by passing through the gas.","A spectrum containing bright lines with little continuous background.","A spectrum shifted toward longer wavelengths throughout."],"Atoms in the cool gas absorb photons whose energy exactly matches the gap between two of their allowed energy levels, removing those specific wavelengths from the transmitted light and producing dark absorption lines in an otherwise continuous spectrum.");
pq("U15","15.3","Emission and Absorption Spectra","3.A","Every element produces its own unique pattern of spectral lines, different from every other element's pattern. What does this fact make spectral analysis useful for?","Identifying which elements are present in a distant light source.",["Determining an object's exact physical size from its spectrum alone.","Measuring an object's electric charge directly from its emitted light.","Proving that all elements have identical internal atomic structure."],"Because each element's unique set of electron energy levels produces a distinctive pattern of spectral lines, matching observed wavelengths to known atomic spectra reveals which elements are present in a light source, a technique widely used in astronomy.");

pq("U15","15.4","Blackbody Radiation","1.A","As an object's temperature increases, how does the wavelength at which it radiates most intensely (its peak wavelength) change?","The peak wavelength becomes shorter, shifting the radiation toward higher-energy colors.",["The peak wavelength becomes longer, shifting the radiation toward lower-energy colors.","The peak wavelength stays exactly the same regardless of temperature.","The object stops radiating any electromagnetic energy at high temperature."],"Hotter blackbody radiators peak at shorter wavelengths, which is why an object glowing red is cooler than one glowing white or blue-white; this inverse relationship between temperature and peak wavelength is a defining feature of thermal radiation.");
pq("U15","15.4","Blackbody Radiation","3.A","Classical physics predicted that a blackbody should radiate infinite energy at very short wavelengths, a failure historically called the ultraviolet catastrophe. What resolved this contradiction with observed blackbody spectra?","The quantum hypothesis that energy is emitted only in discrete packets.",["The discovery that blackbodies do not actually exist in nature.","The realization that temperature has no effect on radiated energy.","The finding that all radiation is emitted only at infrared wavelengths."],"Planck's quantum hypothesis, that oscillators can only emit or absorb energy in discrete quanta rather than continuously, correctly predicted the observed blackbody spectrum and resolved the classical prediction of infinite short-wavelength energy.");

pq("U15","15.5","The Photoelectric Effect","2.A","In a photoelectric experiment, the metal's work function is 2.0 eV, and incoming photons have energy 3.5 eV. Using KEmax = hf − φ, what is the maximum kinetic energy of an ejected electron?","1.5 eV",["3.5 eV","5.5 eV","2.0 eV"],"Maximum kinetic energy is the photon energy minus the work function: KEmax = 3.5 − 2.0 = 1.5 eV.");
pq("U15","15.5","The Photoelectric Effect","3.B","In a photoelectric experiment, the intensity of light striking the metal surface is increased while its frequency stays exactly the same, above the threshold frequency. What effect does this have on the ejected photoelectrons?","It increases photoelectrons per second, but not their maximum kinetic energy.",["It increases the maximum kinetic energy of each ejected photoelectron.","It has no effect at all on the photoelectric emission.","It decreases both the number of photoelectrons and their kinetic energy."],"Photoelectric maximum kinetic energy depends only on individual photon energy (hf) and the metal's work function, not on light intensity. Increasing intensity delivers more photons per second, ejecting more electrons per second, without changing each electron's maximum kinetic energy.");
pq("U15","15.5","The Photoelectric Effect","1.A","A metal's work function is 2.0 eV. Below what threshold frequency will no photoelectrons be ejected from this metal, regardless of the light's intensity?","About 4.8×10^14 Hz; below this, photons lack enough energy to eject electrons.",["Any frequency will eject electrons as long as the light is intense enough.","Exactly 2.0 Hz, matching the numeric value of the work function.","There is no threshold frequency; only wavelength matters for photoelectric emission."],"The threshold frequency satisfies hf0 = φ, so f0 = φ/h = (2.0 eV converted to joules)/(6.63×10^−34) ≈ 4.8×10^14 Hz. Below this frequency, individual photons lack enough energy to eject an electron regardless of how many photons (how intense the light) arrive.");

pq("U15","15.6","Compton Scattering","3.A","In Compton scattering, a photon collides with a nearly free electron and scatters at a nonzero angle from its original direction. What happens to the photon's wavelength as a result of this collision?","The wavelength increases, since the photon transfers energy to the electron.",["The wavelength decreases, since the photon gains energy from the electron.","The wavelength stays exactly the same, since photons cannot lose energy in collisions.","The photon's wavelength becomes undefined after any collision."],"In Compton scattering, the photon loses energy to the recoiling electron, and since photon energy E = hc/λ, a lower-energy photon corresponds to a longer wavelength, an experimentally confirmed wavelength shift.");
pq("U15","15.6","Compton Scattering","1.A","Compton scattering, in which photons scatter off electrons while transferring measurable momentum, provides strong evidence for which aspect of light's behavior?","Light behaves as discrete particles (photons) carrying quantized momentum.",["Light behaves purely as a continuous wave with no particle-like momentum at all.","Light has no measurable momentum under any circumstances.","Electrons behave as continuous waves rather than as particles in this interaction."],"The measurable, angle-dependent momentum and energy transfer between photon and electron in Compton scattering is difficult to explain with a purely wave picture of light, and instead strongly supports treating photons as particles carrying quantized momentum p = h/λ.");

pq("U15","15.7","Fission, Fusion, and Nuclear Decay","2.A","A nuclear reaction converts 3.0×10^−30 kg of mass into energy. Using E = mc^2 with c = 3.00×10^8 m/s, how much energy is released?","About 2.7×10^−13 J",["About 9.0×10^8 J","About 5.4×10^−13 J","About 2.7×10^−22 J"],"Mass-energy equivalence gives E = mc^2 = (3.0×10^−30)(3.00×10^8)^2 = (3.0×10^−30)(9.00×10^16) ≈ 2.7×10^−13 J.");
pq("U15","15.7","Fission, Fusion, and Nuclear Decay","1.A","In nuclear fission, a heavy nucleus splits into two lighter nuclei, releasing energy in the process. What does this reveal about the relative binding energy per nucleon of the original nucleus compared with the fragments?","The original nucleus has lower binding energy per nucleon than the fragments, so splitting releases energy.",["The original heavy nucleus has a higher binding energy per nucleon than the fragments, so splitting releases energy.","Binding energy per nucleon is identical for the original nucleus and the fragments in every fission reaction.","Fission releases energy without any relationship to binding energy per nucleon."],"Energy is released in fission because the fragment nuclei are more tightly bound (higher binding energy per nucleon) than the original heavy nucleus, converting the resulting mass difference into released energy, consistent with the general trend of binding energy per nucleon peaking near iron.");
pq("U15","15.7","Fission, Fusion, and Nuclear Decay","3.A","Very light nuclei, such as isotopes of hydrogen, can release energy when they fuse into a heavier nucleus, while very heavy nuclei release energy when they split apart through fission. What single concept explains both of these seemingly opposite processes?","Both processes move nucleons toward greater binding energy per nucleon, releasing the mass-energy difference.",["Fusion and fission are unrelated processes governed by completely different physical laws.","Fission releases energy, but fusion actually requires a continuous energy input to sustain itself.","Both processes tend to release similar amounts of energy per reaction regardless of the nuclei involved."],"Binding energy per nucleon is low for very light nuclei and very heavy nuclei, and highest for mid-mass nuclei near iron. Both fusing light nuclei and splitting heavy nuclei move nucleons toward higher binding energy per nucleon, releasing energy as a result.");

pq("U15","15.8","Types of Radioactive Decay","1.A","A nucleus undergoes alpha decay, emitting an alpha particle (2 protons and 2 neutrons). How do the resulting nucleus's mass number and atomic number compare with the original nucleus?","The mass number decreases by 4, and the atomic number decreases by 2.",["The mass number decreases by 2, and the atomic number decreases by 4.","The mass number and atomic number both stay exactly the same.","The mass number increases by 4, and the atomic number decreases by 2."],"An alpha particle is a helium-4 nucleus, carrying away 2 protons and 2 neutrons. The daughter nucleus therefore has its mass number reduced by 4 and its atomic number reduced by 2 compared with the parent.");
pq("U15","15.8","Types of Radioactive Decay","1.B","A nucleus undergoes beta-minus decay, in which a neutron converts into a proton while emitting an electron and an antineutrino. How does the resulting nucleus's atomic number compare with the original, and what happens to its mass number?","The atomic number increases by 1, while the mass number stays the same.",["The atomic number decreases by 1, while the mass number increases by 1.","Both the atomic number and mass number stay exactly the same.","The atomic number stays the same, while the mass number decreases by 1."],"Beta-minus decay converts a neutron into a proton within the nucleus, increasing the atomic number (proton count) by 1 while the total number of nucleons, and therefore the mass number, remains unchanged.");
pq("U15","15.8","Types of Radioactive Decay","3.A","A sample of radioactive material has a half-life of 10 days. Starting with a sample of a certain initial activity, approximately what fraction of the original radioactive nuclei remain after 30 days?","About 1/8 of the original amount.",["About 1/3 of the original amount.","About 1/30 of the original amount.","About 1/10 of the original amount."],"Thirty days corresponds to exactly three half-lives (30/10 = 3). Each half-life halves the remaining amount, so after three half-lives the fraction remaining is (1/2)^3 = 1/8 of the original amount.");

